import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"ACP 与编辑器协议：Client 与 Agent 的标准握手","description":"","frontmatter":{"title":"ACP 与编辑器协议：Client 与 Agent 的标准握手","date":"2026-09-25T00:00:00.000Z","isComment":true,"categories":["AI","Agent"],"tags":["ACP","Protocol","Editor"]},"headers":[],"relativePath":"32-acp-agent-client-protocol.md","filePath":"32-acp-agent-client-protocol.md","lastUpdated":1790425174000}'),i={name:"32-acp-agent-client-protocol.md"};function l(o,e,r,d,p,c){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="acp-与编辑器协议-client-与-agent-的标准握手" tabindex="-1">ACP 与编辑器协议：Client 与 Agent 的标准握手 <a class="header-anchor" href="#acp-与编辑器协议-client-与-agent-的标准握手" aria-label="Permalink to &quot;ACP 与编辑器协议：Client 与 Agent 的标准握手&quot;">​</a></h1><blockquote><p>ACP（Agent Client Protocol）解决的是「编辑器如何驱动编程 Agent」的标准化——就像 LSP 之于语言工具：Agent 实现一次，任何 ACP 编辑器都能用；编辑器实现一次，整个 ACP Agent 生态即插即用。</p><p><strong>边界：</strong> 本篇管 client↔agent 会话协议。Agent 调工具见 <a href="./31-mcp-and-agent-protocols">31 MCP</a>，agent↔agent 协作是 A2A（不在本仓库范围）。</p><p><strong>配套实验：</strong> <a href="./examples#05-acp-agent">05 ACP Agent</a> — 官方 SDK 实现最小 agent：版本协商、流式 prompt turn、权限请求、取消；内存流对测试，stdio 可被 Zed 直接挂载，<code>--ollama</code> 接本地 gemma4。</p></blockquote><h2 id="先排雷-三个「acp」只有一个活着" tabindex="-1">先排雷：三个「ACP」只有一个活着 <a class="header-anchor" href="#先排雷-三个「acp」只有一个活着" aria-label="Permalink to &quot;先排雷：三个「ACP」只有一个活着&quot;">​</a></h2><table tabindex="0"><thead><tr><th>全称</th><th>方向</th><th>现状</th></tr></thead><tbody><tr><td><strong>Agent Client Protocol</strong>（Zed / JetBrains）</td><td>client ↔ agent</td><td><strong>活跃，本篇主角</strong></td></tr><tr><td>Agent Communication Protocol（IBM/BeeAI）</td><td>agent ↔ agent</td><td>2025-08 并入 A2A，仓库归档</td></tr><tr><td>Agent Connect Protocol（AGNTCY）</td><td>agent ↔ agent</td><td>2026-04 归档</td></tr></tbody></table><p>读旧文章时注意：2025 年中的「ACP」多指 IBM 那个；现在说 ACP 默认是 Zed 的。</p><h2 id="协议版图-acp-补的是哪块" tabindex="-1">协议版图：ACP 补的是哪块 <a class="header-anchor" href="#协议版图-acp-补的是哪块" aria-label="Permalink to &quot;协议版图：ACP 补的是哪块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>连接</th><th>类比</th></tr></thead><tbody><tr><td>MCP</td><td>agent ↔ 工具/数据</td><td>USB 接口</td></tr><tr><td><strong>ACP</strong></td><td><strong>client（编辑器/CLI）↔ agent</strong></td><td><strong>LSP</strong></td></tr><tr><td>A2A</td><td>agent ↔ agent</td><td>微服务间 RPC</td></tr></tbody></table><p>三者组合不冲突：编辑器通过 ACP 驱动 agent；agent 自己是 MCP client，<code>session/new</code> 时 client 可把 MCP server 列表一并交给 agent。</p><h2 id="通信模型" tabindex="-1">通信模型 <a class="header-anchor" href="#通信模型" aria-label="Permalink to &quot;通信模型&quot;">​</a></h2><ul><li>JSON-RPC 2.0；本地 agent 是编辑器子进程，走 <strong>stdio ndjson</strong>；远程 agent（HTTP/WebSocket）仍是 WIP。</li><li>方法是有响应的请求，通知是单向消息；<code>_meta</code> 字段和 <code>_</code> 前缀方法做扩展。</li><li>用户可读文本默认 Markdown；文件路径必须绝对路径，行号 1-based。</li></ul><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Client（编辑器）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant A as Agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;A: initialize（协议版本 + clientCapabilities）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A--&gt;&gt;C: 协商后版本 + agentCapabilities + authMethods</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    opt 需要认证</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C-&gt;&gt;A: authenticate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;A: session/new（cwd + 可选 MCP servers）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A--&gt;&gt;C: sessionId</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    loop 每个 prompt turn</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C-&gt;&gt;A: session/prompt（ContentBlock[]）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A-&gt;&gt;C: session/update（plan / agent_message_chunk / tool_call ...）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        opt 敏感操作</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            A-&gt;&gt;C: session/request_permission</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            C--&gt;&gt;A: selected / cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        opt 用户打断</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            C-&gt;&gt;A: session/cancel（通知）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            A--&gt;&gt;C: prompt 响应 stopReason=cancelled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A--&gt;&gt;C: prompt 响应 stopReason=end_turn</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>三个容易做错的点：</p><ol><li><strong>版本协商是强制的</strong>：client 报自己支持的最新主版本；agent 支持则回同样版本，否则回自己最新的；client 不接受就断连。实验 05 用 <code>Math.min</code> 演示回退。</li><li><strong>取消不能是报错</strong>：<code>session/cancel</code> 后 agent 必须停掉模型请求和工具调用，prompt 响应 <code>stopReason: &quot;cancelled&quot;</code>——把 abort 异常原样抛成 JSON-RPC error 是实现错误。</li><li><strong>能力省略即不支持</strong>：initialize 里没声明的能力一律视为不支持，新增能力不算 breaking change。</li></ol><h2 id="session-update-的-11-种变体" tabindex="-1">session/update 的 11 种变体 <a class="header-anchor" href="#session-update-的-11-种变体" aria-label="Permalink to &quot;session/update 的 11 种变体&quot;">​</a></h2><p>流式体验全靠这个通知。<code>params.update.sessionUpdate</code> 区分：</p><table tabindex="0"><thead><tr><th>变体</th><th>用途</th></tr></thead><tbody><tr><td><code>agent_message_chunk</code> / <code>agent_thought_chunk</code> / <code>user_message_chunk</code></td><td>流式正文 / 思考过程 / 回显用户消息（同 messageId 属同一条）</td></tr><tr><td><code>tool_call</code> / <code>tool_call_update</code></td><td>新工具调用 / 状态推进（pending→in_progress→completed/failed）</td></tr><tr><td><code>plan</code></td><td>执行计划条目（content/priority/status）</td></tr><tr><td><code>available_commands_update</code></td><td>斜杠命令集变化</td></tr><tr><td><code>current_mode_update</code> / <code>config_option_update</code></td><td>会话模式 / 配置项变化</td></tr><tr><td><code>session_info_update</code></td><td>标题等元数据</td></tr><tr><td><code>usage_update</code></td><td>context 用量与累计成本（used/size token 数，cost 可选）</td></tr></tbody></table><h2 id="能力协商要点" tabindex="-1">能力协商要点 <a class="header-anchor" href="#能力协商要点" aria-label="Permalink to &quot;能力协商要点&quot;">​</a></h2><ul><li><strong>clientCapabilities</strong>：<code>fs.readTextFile/writeTextFile</code>（agent 经 client 读写文件，权限留在编辑器侧）、<code>terminal</code>（agent 经 client 跑命令）、<code>elicitation</code>（结构化向用户提问）。</li><li><strong>agentCapabilities</strong>：<code>loadSession</code>（会话恢复）、<code>promptCapabilities</code>（image/audio/embeddedContext，文本和 resource_link 是基线必有）、<code>mcpCapabilities</code>（agent 能连 http/sse 的 MCP server）。</li></ul><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li>会话状态归 agent，展示与权限归 client——编辑器永远掌握文件写法和命令执行的最终批准权。</li><li>敏感操作必须走 <code>session/request_permission</code>，给出 <code>allow_once/reject_once</code> 等明确选项。</li><li>流式优先：先回 chunk 再慢慢完善，不等完整答案。</li><li>复用 MCP 的 JSON 表示（ContentBlock 等），减少双向翻译。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>initialize 完成版本与能力协商，版本不匹配能回退或断连。</li><li>prompt turn 全程流式，stopReason 语义正确（end_turn/max_tokens/max_turn_requests/refusal/cancelled）。</li><li>敏感操作未经权限确认不执行。</li><li>cancel 后模型请求与工具调用真正中断，且不以报错形式呈现。</li><li>以上四条在实验 05 均有可运行测试（9 条用例，内存流对，不起进程）。</li></ul><h2 id="生态与落地" tabindex="-1">生态与落地 <a class="header-anchor" href="#生态与落地" aria-label="Permalink to &quot;生态与落地&quot;">​</a></h2><ul><li>编辑器：Zed 原生，JetBrains 共建，VS Code 有插件。</li><li>Agent：Claude Code、Gemini CLI、Codex CLI 等均已支持；Gemini CLI 的 agent 侧实现是官方推荐的完整参考。</li><li>SDK：<code>@agentclientprotocol/sdk</code>（TS，v1.5.x 稳定；v2 是 draft，import 路径带 <code>/experimental/v2</code> 才启用）。</li></ul><h2 id="实践任务" tabindex="-1">实践任务 <a class="header-anchor" href="#实践任务" aria-label="Permalink to &quot;实践任务&quot;">​</a></h2><ol><li>实现最小 agent：initialize/new/prompt/cancel 四个基线方法（05 已完成）。</li><li>为敏感操作接 request_permission，验证 allow/reject 两条路径（05 已完成）。</li><li>把 agent 挂到 Zed，对比自研 client 与真实编辑器的消息流。</li><li>思考：你的 agent 哪些能力该声明？<code>loadSession</code> 需要什么持久化？</li></ol><h2 id="与已有内容的关系" tabindex="-1">与已有内容的关系 <a class="header-anchor" href="#与已有内容的关系" aria-label="Permalink to &quot;与已有内容的关系&quot;">​</a></h2><ul><li>MCP 与整体协议版图见 <a href="./31-mcp-and-agent-protocols">31</a>。</li><li>Agent 侧的超时、审批、熔断护栏见 <a href="./30-agent-reliability-and-security">30</a>——ACP 的权限请求是其中「审批」在协议层的标准形态。</li><li>取消与中断的工程实现见 <a href="./08-build-first-agent">08</a> 的 Agent 循环。</li></ul>`,29)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
